<template><ConsumerShell><ConsumerState v-if="error" title="这张运动名片暂未公开" :description="error"/><section v-else-if="card" class="athlete-card consumer-card"><span class="small">运动名片</span><SportsProfileCard :honors="certifiedHonors" :sport-id="primarySportId"><SportsAvatar :nickname="card.display.nickname" :account-id="String(route.params.id)" :avatar-file-id="card.display.avatar_file_id" public-avatar :tone="card.display.avatar_style" :title="card.sports[0]?.title" :title-code="card.sports[0]?.title_code" :points="card.sports[0]?.points||0" :rank-level="card.sports[0]?.rank_index" :rank-name="card.sports[0]?.rank_name"/></SportsProfileCard><p v-if="honorError" class="certified-read-error">认证荣誉暂时无法读取</p><p>{{ card.display.tagline }}</p><div v-for="sport in card.sports" :key="sport.sport_name"><h3>{{ sport.sport_name }} · {{ sport.points }}成长分</h3><p>完赛 {{ sport.finish_count }} 场 · {{ sport.title || '未佩戴称号' }}</p></div><small>查询时间 {{ businessTime(card.generatedAt) }} · 以本页最新状态为准</small><router-link class="btn primary" to="/public/events">查看赛事</router-link></section><ConsumerState v-else loading title="正在打开运动名片"/></ConsumerShell></template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import request from '@/utils/request';import {businessTime} from '@/utils/business';import ConsumerShell from '@/layout/consumer/ConsumerShell.vue';import ConsumerState from '@/components/consumer/ConsumerState.vue';import SportsAvatar from '@/components/consumer/SportsAvatar.vue';import SportsProfileCard from '@/components/consumer/SportsProfileCard.vue';import {publicCertifiedHonors} from '@/api/sports/certifiedDisplay';import type {CertifiedHonor} from '@/api/sports/honorCertification';
const route=useRoute(),error=ref(''),card=ref<{display:{nickname:string;avatar_style:string;avatar_file_id?:string|null;tagline:string};generatedAt:string;sports:{sport_id:string;sport_name:string;points:number;rank_index?:number;rank_name?:string;finish_count:number;title:string|null;title_code?:string|null}[]}>();
const certifiedHonors=ref<CertifiedHonor[]>([]),honorError=ref(false);const primarySportId=computed(()=>card.value?.sports[0]?.sport_id||certifiedHonors.value.find(honor=>honor.worn)?.sportId);
onMounted(async()=>{try{card.value=(await request({url:'/sports/display/public/'+route.params.id,headers:{isToken:false}})).data;try{certifiedHonors.value=(await publicCertifiedHonors(String(route.params.id))).data;}catch{honorError.value=true;}}catch(e){error.value=e instanceof Error?e.message:'名片主人可以决定是否公开';}});
</script>
<style scoped>.athlete-card{margin:35px auto;max-width:590px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:25px;padding:39px;background:linear-gradient(145deg,#fffdfa,#efe7d7)!important;border:1px solid #e3d5b8!important;border-radius:25px!important}.athlete-card>.small{color:#a49374;font-size:10px;letter-spacing:.09em}.athlete-card>p{color:#9a896a;font-size:12px;line-height:1.8;margin:0}.athlete-card>div:not(.sports-avatar):not(.sports-profile-card){border-top:1px solid #e0d4bd;width:100%;padding-top:23px}.athlete-card h3{font-size:18px;font-weight:600;color:#826b44;margin:0 0 11px}.athlete-card>div>p{font-size:11px;color:#a39478;line-height:1.8}.athlete-card small{color:#a69a83;font-size:10px;line-height:1.8}.athlete-card>.btn{font-size:12px}@media(max-width:650px){.athlete-card{padding:30px 24px;margin:24px auto;border-radius:22px!important}.athlete-card h3{font-size:17px}}</style>
